/**
 * 首页美食轮播：8 张高清中餐图以 data URI 内联（发布网关会拦截本地静态资源，故内联）。
 * 暴露 EatWhat.carouselHtml() 返回 HTML，EatWhat.mountCarousel() 启动自动播放/手势。
 */
(function (EatWhat) {
  var SLIDES = [
    { src: "data:image/webp;base64,", cap: "一碗热乎，先暖胃" },
    { src: "data:image/webp;base64,", cap: "宿舍夜宵，就来这口" },
    { src: "data:image/webp;base64,", cap: "下沙的烟火气" },
    { src: "data:image/webp;base64,", cap: "辣得过瘾才够味" },
    { src: "data:image/webp;base64,", cap: "简单一顿也满足" },
    { src: "data:image/webp;base64,", cap: "深夜放毒时间" },
    { src: "data:image/webp;base64,", cap: "下课冲刺第一站" },
    { src: "data:image/webp;base64,", cap: "同学都说这家行" }
  ];

  var idx = 0;
  var timer = null;
  var INTERVAL = 3600;
  var paused = false;
  var REDUCED = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
  var CAN_HOVER = !!(window.matchMedia && window.matchMedia('(hover: hover)').matches);

  // 每张 slide 自带文案与遮罩，随图片一起淡入淡出，保证图文完全同步、不闪烁。
  function carouselHtml() {
    var dots = '';
    for (var i = 0; i < SLIDES.length; i++) {
      dots += '<button class="car-dot' + (i === 0 ? ' car-dot-on' : '') + '" data-car-dot="' + i +
        '" aria-label="第' + (i + 1) + '张" aria-current="' + (i === 0 ? 'true' : 'false') + '"></button>';
    }
    var slides = '';
    for (var j = 0; j < SLIDES.length; j++) {
      var on = j === 0;
      slides += '<div class="car-slide' + (on ? ' car-slide-on' : '') + '" data-car-slide="' + j +
        '" aria-hidden="' + (on ? 'false' : 'true') + '">' +
        '<img class="car-img" src="' + SLIDES[j].src + '" alt="' + SLIDES[j].cap + '" loading="' + (j === 0 ? 'eager' : 'lazy') + '" />' +
        '<div class="car-shade"></div>' +
        '<div class="car-caption"><span class="car-cap-text">' + SLIDES[j].cap + '</span></div>' +
        '</div>';
    }
    return '<div class="car" id="car" aria-roledescription="carousel" aria-label="下沙美食">' +
      '<div class="car-track" id="car-track">' + slides + '</div>' +
      '<div class="car-dots" id="car-dots">' + dots + '</div>' +
      '</div>';
  }

  function show(n) {
    var slides = document.querySelectorAll('#car .car-slide');
    var dots = document.querySelectorAll('#car .car-dot');
    if (!slides.length) return;
    var next = (n + SLIDES.length) % SLIDES.length;
    if (next === idx) return;
    idx = next;
    for (var i = 0; i < slides.length; i++) {
      var on = i === idx;
      slides[i].classList.toggle('car-slide-on', on);
      slides[i].setAttribute('aria-hidden', on ? 'false' : 'true');
      if (dots[i]) {
        dots[i].classList.toggle('car-dot-on', on);
        dots[i].setAttribute('aria-current', on ? 'true' : 'false');
      }
    }
  }

  function play() {
    stop();
    if (REDUCED || paused) return;
    timer = setInterval(function () { show(idx + 1); }, INTERVAL);
  }
  function stop() { if (timer) { clearInterval(timer); timer = null; } }
  function pause() { paused = true; stop(); }
  function resume() { paused = false; play(); }

  function mountCarousel() {
    var car = document.getElementById('car');
    if (!car) return;
    var dotsWrap = document.getElementById('car-dots');
    if (dotsWrap) {
      dotsWrap.addEventListener('click', function (e) {
        var d = e.target.getAttribute && e.target.getAttribute('data-car-dot');
        if (d !== null && d !== undefined) { show(parseInt(d, 10)); play(); }
      });
    }
    // 桌面端：悬停/键盘聚焦时暂停，移出后继续，方便细看与点击指示器
    if (CAN_HOVER) {
      car.addEventListener('mouseenter', pause);
      car.addEventListener('mouseleave', resume);
      car.addEventListener('focusin', pause);
      car.addEventListener('focusout', resume);
    }
    // 移动端：横向滑动切换，纵向滚动不干扰
    var startX = null, startY = null;
    car.addEventListener('touchstart', function (e) {
      var t = e.touches[0];
      startX = t.clientX; startY = t.clientY;
      stop();
    }, { passive: true });
    car.addEventListener('touchend', function (e) {
      if (startX === null) return;
      var t = e.changedTouches[0];
      var dx = t.clientX - startX;
      var dy = t.clientY - startY;
      if (Math.abs(dx) > 40 && Math.abs(dx) > Math.abs(dy)) show(idx + (dx < 0 ? 1 : -1));
      startX = null; startY = null;
      if (!paused) play();
    }, { passive: true });
    // 切到后台暂停，省电且避免回前台时连续跳帧
    document.addEventListener('visibilitychange', function () {
      if (document.hidden) stop();
      else if (!paused) play();
    });
    play();
  }

  EatWhat.carouselHtml = carouselHtml;
  EatWhat.mountCarousel = mountCarousel;
})(window.EatWhat = window.EatWhat || {});
